// Ownership is decided from the event Google actually holds, never from text the
// model supplied. The old guard compared ref: inside a description the agent
// retyped, so passing your own booking's description with someone else's event
// id would have passed it.
//
// The id itself is now checked against the calendar too. On 2026-08-30 the model
// was shown seven search results and passed an eighth id that existed in none of
// them - invented, in the shape of the recurring-instance ids it had just seen.
// Get Event returned 404 and that read as "the booking is gone", which is a
// different and much more reassuring thing than "you made that id up". So the
// day's events are listed and the id has to be one of them.
const REQ = $('When Executed by Another Workflow').first().json;
const raw = $input.first().json || {};
const me  = String(REQ.requester || '').trim();
const confirmed = REQ.confirmed === true || String(REQ.confirmed).toLowerCase() === 'true';
const wanted = String(REQ.event_id || '').trim();

if (!confirmed) {
  return [{ json: { verdict:'REJECTED', reason:'NOT_CONFIRMED',
    human:'Nothing was cancelled. Show the requester the booking you found, end that message with the line "Confirm to cancel. (y/n)", and stop. Cancel it only after they reply y.' } }];
}
if (!String(REQ.booking_date || '').trim()) {
  return [{ json: { verdict:'REJECTED', reason:'MISSING_DATE',
    human:'Nothing was cancelled - no booking date was given. Search for the booking again and pass the date it falls on.' } }];
}
if (!wanted) {
  return [{ json: { verdict:'REJECTED', reason:'MISSING_ID',
    human:'Nothing was cancelled - no event id was given. Search for the booking again and use the id from the result.' } }];
}

const items = Array.isArray(raw.items) ? raw.items : null;
if (!items) {
  return [{ json: { verdict:'REJECTED', reason:'LOOKUP_FAILED',
    human:'Nothing was cancelled - the calendar could not be read for that date. Tell the requester it did not go through and offer to try again.' } }];
}

const ev = items.find(e => String(e.id) === wanted);
if (!ev) {
  // The id was not on the calendar that day. Hand back what actually is, so the
  // next attempt uses a real id instead of another invented one.
  const real = items
    .filter(e => e.status !== 'cancelled')
    .map(e => '- ' + (e.summary || '(no title)') + '  id: ' + e.id);
  return [{ json: { verdict:'REJECTED', reason:'ID_NOT_ON_CALENDAR',
    human: 'Nothing was cancelled. The id you gave is not on the calendar for that date, so it did not come from a '
      + 'search result. Do not send it again and do not adapt it. These are the only bookings on that date, with '
      + 'their real ids:\n' + (real.join('\n') || '(none)')
      + '\nIf one of them is the booking, call Cancel Booking again with that exact id. If none of them is, tell '
      + 'the requester the booking was not found and ask them to check the date.' } }];
}

const desc = String(ev.description || '');
const ref  = desc.match(/ref:\s*([A-Za-z0-9]+)/);
const by   = desc.match(/Booked by:\s*([^|]+)/);
const who  = by ? by[1].trim() : '';
const title = ev.summary || '(no title)';

if (!ref) {
  return [{ json: { verdict:'REJECTED', reason:'NO_REFERENCE', title,
    human:'BLOCKED - "' + title + '" carries no booker reference, so there is no way to tell whose it is. It has to be cancelled by hand.' } }];
}
if (ref[1] !== me) {
  return [{ json: { verdict:'REJECTED', reason:'NOT_YOURS', title,
    human:'BLOCKED - "' + title + '" was booked by ' + (who || 'someone else') + ', so it is not yours to cancel. Ask them to cancel it, or have it done by hand.' } }];
}
return [{ json: { verdict:'CLEAR', event_id: ev.id, title,
  start: (ev.start && (ev.start.dateTime || ev.start.date)) || '' } }];

const c = $('Check Ownership').first().json;
return [{ json: { status:'CANCELLED', event_id: c.event_id, title: c.title,
  human:'Cancelled "' + c.title + '".' } }];

const v = $input.first().json || {};
return [{ json: { status:'REJECTED', reason: v.reason || 'FAILED',
  human: v.human || 'Nothing was cancelled and the reason is unclear. Tell the requester it did not go through.' } }];

// Ownership is decided from the event Google actually holds, never from text the
// model supplied. The old guard compared ref: inside a description the agent
// retyped, so passing your own booking's description with someone else's event
// id would have passed it.
const REQ = $('When Executed by Another Workflow').first().json;
const ev  = $input.first().json || {};
const me  = String(REQ.requester || '').trim();
const confirmed = REQ.confirmed === true || String(REQ.confirmed).toLowerCase() === 'true';

if (!confirmed) {
  return [{ json: { verdict:'REJECTED', reason:'NOT_CONFIRMED',
    human:'Nothing was cancelled. Show the requester the booking you found, end that message with the line "Confirm to cancel.", and stop. Cancel it only after they reply approving it.' } }];
}
if (!ev.id) {
  return [{ json: { verdict:'REJECTED', reason:'NOT_FOUND',
    human:'Nothing was cancelled - that booking no longer exists on the calendar. Tell the requester and offer to search again.' } }];
}

const desc = String(ev.description || '');
const ref  = desc.match(/ref:\s*([A-Za-z0-9]+)/);
const by   = desc.match(/Booked by:\s*([^|]+)/);
const who  = by ? by[1].trim() : '';
const title = ev.summary || '(no title)';

if (!ref) {
  return [{ json: { verdict:'REJECTED', reason:'NO_REFERENCE', title,
    human:'BLOCKED - "' + title + '" carries no booker reference, so it cannot be confirmed as theirs. It was made before booker tracking, or created directly in Google Calendar. Tell the requester it has to be cancelled in Google Calendar instead. Nothing was cancelled.' } }];
}
if (ref[1] !== me) {
  return [{ json: { verdict:'REJECTED', reason:'NOT_YOURS', title, booked_by: who || null,
    human:'BLOCKED - "' + title + '" was booked by ' + (who || 'someone else') + '. Only the person who made a booking can cancel it. Tell the requester who to coordinate with and do not try again. Nothing was cancelled.' } }];
}
return [{ json: { verdict:'CLEAR', event_id: ev.id, title,
  start: (ev.start && (ev.start.dateTime || ev.start.date)) || '' } }];

const c = $('Check Ownership').first().json;
return [{ json: { status:'CANCELLED', event_id: c.event_id, title: c.title,
  human:'Cancelled "' + c.title + '".' } }];

const v = $input.first().json || {};
return [{ json: { status:'REJECTED', reason: v.reason || 'FAILED',
  human: v.human || 'Nothing was cancelled and the reason is unclear. Tell the requester it did not go through.' } }];
